    for t in tgts: sched.append((t,t+0.15,0.5,210.0))
    for t in nuis: sched.append((t,t+0.2,0.8,250.0))
    return sim.simulate(L,auxL,C,gate,thr,sched,T=30.0,dt=1e-4)
for C in [80,100,120,150]:
    for gate in [2.0,2.2,2.4]:
        r=run(C,gate)
        ss=1-r['max_stress']/40e6; st=1-r['max_travel']/1.5e-3
        # count reports and wakes
        wakes=[e for e in r['events'] if e[0]=='wake']
        print(f"C={C} gate={gate} rep={r['reports']} brown={r['brown']} wakes={len(wakes)} vs_end={r['vs']:.2f} slope_s={ss:.2f} slapt={st:.2f}")
"}

